// ============================================================
// Rule: THM_Detection of Persistence via Registry Run Key with Suspicious JavaScript
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Detection of Persistence via Registry Run Key with Suspicious JavaScript.
// Severity: SEV_050_CRITICAL
// Category: EVASION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1547.001 - Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder
// Tactic: TA0004 - Privilege Escalation
// Technique: T1547.001 - Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder

// Desabilita diferenciação entre maiúsculas e minúsculas para comparações
config case_sensitive = false  

// Define o dataset de origem como dados brutos do Cortex XDR
| dataset = xdr_data  

// Filtra apenas eventos do tipo "REGISTRY" (modificação no Registro do Windows)
| filter event_type = ENUM.REGISTRY  

// Filtra apenas eventos de alteração de valor no registro
| filter event_sub_type = ENUM.REGISTRY_SET_VALUE  

// Busca alterações na chave de inicialização automática de programas do Windows
| filter action_registry_key_name contains "Software\\Microsoft\\Windows\\CurrentVersion\\Run"  

// Restringe para valores de registro que apontem para scripts .JS na pasta Public\Downloads
| filter (`action_registry_data` = """*C:\\Users\\Public\\Downloads\\*.js*""")  

// Seleciona os campos relevantes para análise e resposta
| fields agent_hostname,                      // Nome do host onde ocorreu o evento
         actor_process_image_name,             // Nome do processo que executou a ação
         actor_process_command_line,           // Linha de comando usada pelo processo
         action_registry_key_name,             // Caminho da chave de registro modificada
         action_registry_value_name,           // Nome do valor de registro alterado
         action_registry_data                  // Dados atribuídos ao valor de registro
